import{_ as a,o as e,c as r,a2 as t}from"./chunks/framework.1C62pOns.js";const s="/pro-agent-hub-installer/capturas/pt/workflows-detalhe.png",d="/pro-agent-hub-installer/capturas/pt/workflows-fluxo.png",n="/pro-agent-hub-installer/capturas/pt/workflows-codigo.png",c="/pro-agent-hub-installer/capturas/pt/workflows-versoes.png",i="/pro-agent-hub-installer/capturas/pt/execucoes-lista.png",l="/pro-agent-hub-installer/capturas/pt/execucoes-detalhe.png",w=JSON.parse('{"title":"Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"pt/interface/workflows.md","filePath":"pt/interface/workflows.md","lastUpdated":1787856241000}'),u={name:"pt/interface/workflows.md"};function p(m,o,g,h,f,b){return e(),r("div",null,[...o[0]||(o[0]=[t('<h1 id="workflows" tabindex="-1">Workflows <a class="header-anchor" href="#workflows" aria-label="Permalink to &quot;Workflows&quot;">​</a></h1><p>Um <strong>workflow</strong> é uma automação: uma sequência de passos que a plataforma executa sozinha — manualmente, por agendamento ou chamada de outro lugar.</p><p>Há dois tipos, escolhidos por um par de botões na aba Geral:</p><ul><li><strong>Low-code</strong> — um fluxo desenhado em caixinhas ligadas.</li><li><strong>High-code</strong> — um arquivo Python.</li></ul><p>O tipo pode ser trocado a qualquer momento, e <strong>os dois conteúdos ficam guardados</strong>: virar high-code não apaga o fluxo desenhado, e voltar para low-code não apaga o código. O que muda é qual dos dois a plataforma executa — e qual aba aparece.</p><div class="tip custom-block"><p class="custom-block-title">O co-pilot escreve os dois</p><p>O botão do Pegasus, na aba Geral, aceita um pedido em português e devolve ou um fluxo, ou o Python — e a plataforma reconhece o que veio, troca o tipo e joga o resultado na aba certa. É o caminho mais curto para sair do zero, e também para pedir &quot;transforme este fluxo em código&quot;.</p></div><h2 id="aba-geral" tabindex="-1">Aba Geral <a class="header-anchor" href="#aba-geral" aria-label="Permalink to &quot;Aba Geral&quot;">​</a></h2><p><img src="'+s+'" alt="workflows-detalhe"></p><p>Descrição, grupo e o <strong>agendamento</strong>.</p><p>O agendamento é uma <strong>expressão cron</strong>, avaliada em UTC. A tela mostra as próximas execuções calculadas a partir da expressão — confira ali antes de salvar; é mais rápido do que descobrir no dia seguinte que o horário estava deslocado.</p><div class="tip custom-block"><p class="custom-block-title">Agendado não roda em paralelo consigo mesmo</p><p>Se o horário chega e a execução anterior ainda está rodando, o disparo é <strong>ignorado</strong> e fica registrado como tal. É a garantia de que um processo agendado nunca roda duas vezes ao mesmo tempo. Execuções manuais não têm essa trava.</p></div><p>O <strong>nível de log</strong> define quanto a execução grava: apenas erros, o andamento, ou tudo. Log detalhado ajuda a depurar e pesa no banco — as execuções antigas são podadas pela retenção configurada em <a href="/pro-agent-hub-installer/pt/interface/administracao#configurações">Configurações</a>.</p><h2 id="aba-fluxo-low-code" tabindex="-1">Aba Fluxo (low-code) <a class="header-anchor" href="#aba-fluxo-low-code" aria-label="Permalink to &quot;Aba Fluxo (low-code)&quot;">​</a></h2><p><img src="'+d+'" alt="workflows-fluxo"></p><p>O quadro onde o fluxo é montado. Arraste os nós da paleta, ligue as saídas às entradas e clique em um nó para configurar.</p><p>Os tipos de nó cobrem entrada e saída, condição, laço, chamada de agente, time ou planejador, operações de dados e sistema, e um nó de <strong>script</strong> para o que não couber nos demais.</p><p><strong>Execução ao vivo.</strong> Ao rodar pelo botão de teste, o quadro acompanha:</p><ul><li>o nó em execução fica <strong>pulsando, com borda destacada</strong>;</li><li>ao terminar, ele muda de cor conforme o resultado e mostra o <strong>tempo que levou</strong>;</li><li>os que ainda não rodaram ficam apagados.</li></ul><p>Isso acontece <strong>durante</strong> a execução, nó a nó, e não só no fim. Em fluxo longo, é como se vê onde ele está preso.</p><h2 id="aba-codigo-high-code" tabindex="-1">Aba Código (high-code) <a class="header-anchor" href="#aba-codigo-high-code" aria-label="Permalink to &quot;Aba Código (high-code)&quot;">​</a></h2><p><img src="'+n+'" alt="workflows-codigo"></p><p>Um editor Python com autocompletar das funções da plataforma — digite <code>db_</code> e a lista aparece, com a assinatura e a descrição de cada uma.</p><p>O código roda com um escopo já montado: <code>context</code> (o que entrou), <code>log()</code>, <code>is_cancelled()</code> e as operações de dados, sistema e integração. Não há <code>import</code> obrigatório para usá-las. A referência completa está em <a href="/pro-agent-hub-installer/pt/funcoes/workflow_highcode">Workflow high-code</a>.</p><div class="tip custom-block"><p class="custom-block-title">Workflow longo deve checar cancelamento</p><p>O cancelamento é <strong>cooperativo</strong>: a plataforma marca o pedido, e é o seu código que decide parar. Em laço longo, chame <code>is_cancelled()</code> a cada volta e saia quando ele devolver verdadeiro. Sem isso, cancelar só tem efeito quando a execução termina por conta própria.</p></div><h2 id="aba-execucoes" tabindex="-1">Aba Execuções <a class="header-anchor" href="#aba-execucoes" aria-label="Permalink to &quot;Aba Execuções&quot;">​</a></h2><p>O histórico daquele workflow, com situação, duração e o log de cada execução.</p><h2 id="aba-versoes" tabindex="-1">Aba Versões <a class="header-anchor" href="#aba-versoes" aria-label="Permalink to &quot;Aba Versões&quot;">​</a></h2><p><img src="'+c+'" alt="workflows-versoes"></p><p>Cada gravação guarda uma versão do workflow. A aba lista as versões, permite <strong>comparar</strong> duas (no high-code, com o diff linha a linha) e <strong>restaurar</strong> uma anterior.</p><p>Restaurar não apaga nada: cria uma versão nova com o conteúdo antigo. Nunca se perde o caminho de volta.</p><h2 id="execuções" tabindex="-1">Execuções <a class="header-anchor" href="#execuções" aria-label="Permalink to &quot;Execuções {#execuções}&quot;">​</a></h2><p><img src="'+i+'" alt="execucoes-lista"></p><p>Tela própria, no menu Principal: o monitor de <strong>todas</strong> as execuções da plataforma, e não de um workflow só.</p><p>O filtro é por descrição do workflow, situação e período. Enquanto houver execução ativa, a lista se atualiza sozinha a cada poucos segundos — e um indicador no topo mostra que está acompanhando.</p><p>As situações são:</p><table tabindex="0"><thead><tr><th>Situação</th><th>O que significa</th></tr></thead><tbody><tr><td><strong>Em execução</strong></td><td>Rodando agora.</td></tr><tr><td><strong>Concluída</strong></td><td>Terminou sem erro.</td></tr><tr><td><strong>Com erro</strong></td><td>Terminou com exceção. A mensagem fica no detalhe.</td></tr><tr><td><strong>Cancelando</strong></td><td>Cancelamento pedido; aguardando o processo chegar num ponto de parada.</td></tr><tr><td><strong>Cancelada</strong></td><td>Parou por pedido do usuário.</td></tr><tr><td><strong>Interrompida</strong></td><td>O processo que a executava parou de responder.</td></tr></tbody></table><p><strong>Interrompida</strong> merece atenção: não é erro do seu workflow, é o processo que morreu (contêiner reiniciado, máquina derrubada). A plataforma marca assim quando uma execução deixa de dar sinal de vida por alguns minutos, para não deixar registro preso &quot;em execução&quot; para sempre.</p><p><img src="'+l+'" alt="execucoes-detalhe"></p><p>O detalhe traz a origem (manual, agendada, webhook ou API), quem disparou, a duração, o nó corrente, uma prévia da saída e o log completo.</p><h3 id="cancelar" tabindex="-1">Cancelar <a class="header-anchor" href="#cancelar" aria-label="Permalink to &quot;Cancelar&quot;">​</a></h3><p>O botão de cancelar funciona <strong>também quando a execução foi disparada pelo agendador</strong>, em outro processo — o pedido é gravado no banco e o processo que está executando o lê em segundos.</p><p>No low-code, o cancelamento é verificado entre um nó e outro: um nó já iniciado termina. No high-code, depende do seu <code>is_cancelled()</code>.</p>',42)])])}const q=a(u,[["render",p]]);export{w as __pageData,q as default};
